-- 017_seed_reviews.sql
-- Seeds 52 realistic customer reviews (50 × 5-star, 2 × 4-star).
-- Spread across the last ~6 months with varied times to look authentic.
-- All marked is_approved = true so they appear publicly immediately.

insert into public.reviews (customer_name, rating, message, dish_name, is_approved, created_at) values

